EXPORT ZZT_SDVEC() BEGIN LOCAL R,out:={};
R:=stddev([0,1,3],{2,-.5,1}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev([1,5],{-.25,1.25}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev([1,4,8],{-1.5,-.5,-2.5}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev([3,3,3],{-1.5,.5,2.5}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev([-1,0,1],[1.5,-.5,1.5]); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev([-1,3],[-.5,1.5]); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev([1,-3],[-.5,1.5]); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev([-3,0,4],[1.5,-.5,2]); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev([-3,0,4],[-2.5,-.5,-2]); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev([0+1,3],[-.5,1.5]); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev([-(-1),3],[-.5,1.5]); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev([-0,3],[-.5,1.5]); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
RETURN out; END;

EXPORT ZZT_SDVEC() BEGIN LOCAL R,out:={};
R:=stddev([2,4],{-.25,.25}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev([2,4],{-2,2}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev([-1,3],[-1.5,-1.5]); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev([-1,3],[-1,-2]); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
RETURN out; END;
